ACT['a2-ftsw'] = function(el){ var k = el.getAttribute('data-k'), on = !ft(k).on; ftSet(k, 'on', on); a2Log('Feature ' + k + ' ' + (on ? 'on' : 'off')); rerender(); toast((on ? L('Turned on', 'চালু হয়েছে') : L('Turned off', 'বন্ধ হয়েছে'))); };
ACT['a2-appr'] = function(el){ var x = a2S().appr.filter(function(a){ return a.id === el.getAttribute('data-id'); })[0], ok = el.getAttribute('data-v') === 'ok'; if(!x) return;
  if(!a2Can(x.kind === 'block' ? 'risk.block.confirm' : x.kind === 'refund' ? 'money.refunds.approve' : 'customers.privacy') && a2S().role !== 'owner') return toast(L('Only the owner decides this', 'এটা মালিক ঠিক করেন'));
  a2Confirm({title:(ok ? 'Approve: ' : 'Refuse: ') + x.kindEn, bn:(ok ? 'অনুমোদন: ' : 'না: ') + (x.kindBn || x.kindEn), sub:esc(x.why || ''), effects:ok ? [x.kind === 'codOff' ? L('This number can order with advance payment only; the profile shows “COD off (approved)”', 'এই নম্বরে শুধু অগ্রিমে অর্ডার') : x.kind === 'block' ? L('Orders from this number go to “Blocked match” for review', 'এই নম্বরের অর্ডার ব্লক-মিলে যাবে') : L('The refund becomes approved; Accounts pays it', 'রিফান্ড অনুমোদিত; হিসাব বিভাগ দেবে')] : [L('The proposer is told; nothing changes', 'প্রস্তাবকারী জানবে; কিছু বদলাবে না')], reason:ok ? 'optional' : true, tone:ok ? 'pri' : 'badf',
    fn:function(r){ x.st = ok ? 'approved' : 'refused'; x.decidedBy = a2Who(); x.decidedAt = Date.now(); x.note = r;
      if(ok && x.kind === 'block'){ a2S().risk.block.push({id:'b' + Date.now(), what:a2ph(x.phone), reason:x.why, by:a2Who(), at:Date.now()}); }
      if(ok && x.kind === 'wallet'){ var acc = ST.accounts[String(x.phone).replace(/\D/g, '')]; if(acc){ acc.wallet = (acc.wallet || 0) + x.amt; acc.walletTx = acc.walletTx || []; acc.walletTx.unshift({label:x.src + ' · approved by ' + a2Who(), amount:x.amt, at:Date.now()}); } }
      if(x.kind === 'refund'){ var o = ST.orders[x.ref]; if(o) (a2O(o).refunds || []).forEach(function(f){ if(f.status === 'REQUESTED'){ f.status = ok ? 'APPROVED' : 'REJECTED'; f.approvedBy = a2Who(); } }); }
      a2Log((ok ? 'Approved ' : 'Refused ') + x.kindEn + (x.phone ? ' ' + x.phone : '') + (x.ref ? ' ' + x.ref : '')); saveState(); rerender(); toast(ok ? L('Approved', 'অনুমোদিত') : L('Refused', 'নেওয়া হয়নি')); }}); };
